module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);

    wire [7:0] mul_a_ext = {4'd0, mul_a};
    wire [7:0] mul_b_ext = {4'd0, mul_b};

    wire [7:0] partial_product[3:0];
    genvar i;
    generate
        for(i = 0; i < 4; i = i + 1) begin : gen_partial_products
            assign partial_product[i] = (mul_b_ext[i] ? mul_a_ext << i : 8'd0);
        end
    endgenerate

    reg [7:0] sum_reg[1:0];
    reg [7:0] product;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            sum_reg[0] <= 8'd0;
            sum_reg[1] <= 8'd0;
        end else begin
            sum_reg[0] <= partial_product[0] + partial_product[1];
            sum_reg[1] <= partial_product[2] + partial_product[3];
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            product <= 8'd0;
        end else begin
            product <= sum_reg[0] + sum_reg[1];
        end
    end

    assign mul_out = product;
endmodule
